import "server-only";

import { getCurrentUser } from "@/server/auth/session";
import { createClient } from "@/server/supabase/server";

// Every query here filters by specialist_id = the session user. RLS alone would
// hand a lead every reply of their team, and "my" would stop being true. The id
// comes from the session, never from a parameter (TASK-005, Q1).

export const FEEDBACK_PAGE_SIZE = 20;
const RECENT_SCORES = 5;
/** PostgREST: "Requested range not satisfiable". */
const OFFSET_PAST_END = "PGRST103";

export type BrandScore = {
  brandId: string;
  average: number;
  reviewCount: number;
  criticalCount: number;
};

/** The caller's average, review count and critical count per brand. */
export async function getMyBrandScores(): Promise<BrandScore[]> {
  const { id } = await getCurrentUser();
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("specialist_brand_scores")
    .select("brand_id, avg_score, review_count, critical_count")
    .eq("specialist_id", id);
  if (error) throw error;

  // View columns are typed nullable; the grouping keys and aggregates never are.
  return data.map((r) => ({
    brandId: r.brand_id ?? "",
    average: Number(r.avg_score),
    reviewCount: r.review_count ?? 0,
    criticalCount: r.critical_count ?? 0,
  }));
}

export type IssueCount = {
  brandId: string;
  issueCode: string;
  count: number;
  /** sent_at of the latest reply it was flagged on. */
  lastSentAt: string;
};

/** How often each issue was flagged on the caller's replies, per brand. */
export async function getMyIssueCounts(): Promise<IssueCount[]> {
  const { id } = await getCurrentUser();
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("specialist_issue_counts")
    .select("brand_id, issue_code, flagged_count, last_sent_at")
    .eq("specialist_id", id);
  if (error) throw error;

  return data.map((r) => ({
    brandId: r.brand_id ?? "",
    issueCode: r.issue_code ?? "",
    count: r.flagged_count ?? 0,
    lastSentAt: r.last_sent_at ?? "",
  }));
}

/**
 * The caller's latest scores in one brand, oldest first so they read left to
 * right. Takes the five latest reviewed replies; with two reviews on one reply
 * both count, as they do in the average.
 */
export async function getMyRecentScores(brandId: string): Promise<number[]> {
  const { id } = await getCurrentUser();
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("replies")
    .select("id, reviews!inner(score, updated_at)")
    .eq("specialist_id", id)
    .eq("brand_id", brandId)
    .order("sent_at", { ascending: false })
    .order("id")
    .order("updated_at", { referencedTable: "reviews", ascending: false })
    .limit(RECENT_SCORES);
  if (error) throw error;

  return data
    .flatMap((r) => r.reviews.map((rv) => rv.score))
    .slice(0, RECENT_SCORES)
    .reverse();
}

export type FeedbackReview = {
  id: string;
  reviewerName: string;
  score: number;
  comment: string;
  issueCodes: string[];
  updatedAt: string;
};

export type FeedbackItem = {
  id: string;
  ticketRef: string;
  subject: string;
  sentAt: string;
  brandId: string;
  /** Null when the caller has left the brand: RLS hides the brand row, not their replies. */
  brandName: string | null;
  reviews: FeedbackReview[];
};

export type FeedbackFilters = {
  brandId: string | null;
  issueCode: string | null;
  /** Already cleaned by parseFeedbackParams: no PostgREST syntax characters. */
  search: string | null;
  page: number;
};

export type FeedbackPage = {
  items: FeedbackItem[];
  total: number;
};

/**
 * One page of the caller's reviewed replies, newest first. The filtering and
 * the count run on the reviewed_replies view; the reviews of the page are then
 * read for those ids only.
 */
export async function listMyFeedback(filters: FeedbackFilters): Promise<FeedbackPage> {
  const { id } = await getCurrentUser();
  const supabase = await createClient();

  const matching = (head: boolean) => {
    let query = supabase
      .from("reviewed_replies")
      .select("id", { count: "exact", head })
      .eq("specialist_id", id);
    if (filters.brandId) query = query.eq("brand_id", filters.brandId);
    if (filters.issueCode) query = query.contains("issue_codes", [filters.issueCode]);
    if (filters.search) {
      const pattern = `"%${filters.search}%"`;
      query = query.or(`ticket_ref.ilike.${pattern},subject.ilike.${pattern}`);
    }
    return query;
  };

  const from = (filters.page - 1) * FEEDBACK_PAGE_SIZE;
  const { data: page, count, error } = await matching(false)
    .order("sent_at", { ascending: false })
    .order("id")
    .range(from, from + FEEDBACK_PAGE_SIZE - 1);
  if (error?.code === OFFSET_PAST_END) {
    // PostgREST refuses a range past the last row instead of returning none;
    // the page still needs the total to offer a way back.
    const { count: total, error: countError } = await matching(true);
    if (countError) throw countError;
    return { items: [], total: total ?? 0 };
  }
  if (error) throw error;

  const ids = page.flatMap((r) => (r.id ? [r.id] : []));
  if (ids.length === 0) return { items: [], total: count ?? 0 };

  const { data, error: detailError } = await supabase
    .from("replies")
    .select(
      `id, ticket_ref, subject, sent_at, brand_id,
       brand:brands(name),
       reviews!inner(id, score, comment, updated_at,
                     reviewer:profiles!reviews_reviewer_id_fkey(full_name),
                     review_issues(issue_code))`,
    )
    .eq("specialist_id", id)
    .in("id", ids)
    .order("sent_at", { ascending: false })
    .order("id")
    .order("updated_at", { referencedTable: "reviews", ascending: false });
  if (detailError) throw detailError;

  const items = data.map((r) => ({
    id: r.id,
    ticketRef: r.ticket_ref,
    subject: r.subject,
    sentAt: r.sent_at,
    brandId: r.brand_id,
    // Typed non-null, but null for a brand the caller no longer belongs to.
    brandName: r.brand?.name ?? null,
    reviews: r.reviews.map((rv) => ({
      id: rv.id,
      reviewerName: rv.reviewer?.full_name ?? "Former lead",
      score: rv.score,
      comment: rv.comment,
      issueCodes: rv.review_issues.map((ri) => ri.issue_code),
      updatedAt: rv.updated_at,
    })),
  }));
  return { items, total: count ?? 0 };
}
import type { Membership } from "@/server/auth/session";
import type { BrandScore, IssueCount } from "@/server/data/feedback";
import type { IssueType } from "@/server/data/reviews";

const TOP_ISSUES = 3;
const SEVERITY_RANK = { critical: 0, major: 1, minor: 2 } as const;

export type RepeatedIssue = {
  issue: IssueType;
  count: number;
  lastSentAt: string;
};

export type BrandFeedback = {
  brandId: string;
  /** Null for a brand the specialist has left. */
  name: string | null;
  /** Slug for the filter links; null for a brand the specialist has left. */
  slug: string | null;
  score: BrandScore | null;
  recentScores: number[];
  topIssues: RepeatedIssue[];
};

export function hasCritical(issueCodes: string[], issuesByCode: Map<string, IssueType>): boolean {
  return issueCodes.some((code) => issuesByCode.get(code)?.severity === "critical");
}

/**
 * One card per brand the person covers as a specialist (empty until reviewed),
 * then any brand they have left but still have reviews in. The numbers come
 * from the specialist views, already limited to the person; this only arranges
 * them and picks the top issues: critical first, then the most frequent.
 */
export function arrangeBrandCards(
  memberships: Membership[],
  scores: BrandScore[],
  issueCounts: IssueCount[],
  recentScores: Map<string, number[]>,
  issueTypes: IssueType[],
): BrandFeedback[] {
  const issuesByCode = new Map(issueTypes.map((it) => [it.code, it]));
  const covered = memberships.filter((m) => m.role === "specialist");
  const known = new Map(memberships.map((m) => [m.brandId, m]));
  const brandIds = [
    ...covered.map((m) => m.brandId),
    ...scores.map((s) => s.brandId).filter((id) => !covered.some((m) => m.brandId === id)),
  ];

  return brandIds.map((brandId) => {
    const topIssues = issueCounts
      .filter((c) => c.brandId === brandId)
      .flatMap((c) => {
        const issue = issuesByCode.get(c.issueCode);
        return issue ? [{ issue, count: c.count, lastSentAt: c.lastSentAt }] : [];
      })
      .sort((a, b) => SEVERITY_RANK[a.issue.severity] - SEVERITY_RANK[b.issue.severity] || b.count - a.count)
      .slice(0, TOP_ISSUES);
    const membership = known.get(brandId);
    return {
      brandId,
      name: membership?.name ?? null,
      slug: membership?.slug ?? null,
      score: scores.find((s) => s.brandId === brandId) ?? null,
      recentScores: recentScores.get(brandId) ?? [],
      topIssues,
    };
  });
}
import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { BrandCard } from "@/features/feedback/components/brand-card";
import { FeedbackFilters } from "@/features/feedback/components/feedback-filters";
import { FeedbackList } from "@/features/feedback/components/feedback-list";
import { Pagination } from "@/features/feedback/components/pagination";
import { feedbackHref, parseFeedbackParams } from "@/features/feedback/feedback-params";
import { arrangeBrandCards } from "@/features/feedback/summary";
import { getOptionalUser } from "@/server/auth/session";
import { getMyBrandScores, getMyIssueCounts, getMyRecentScores, listMyFeedback } from "@/server/data/feedback";
import { listIssueTypes } from "@/server/data/reviews";
import { EmptyState } from "@/ui/empty-state";

export const metadata: Metadata = { title: "My feedback · Sellervate QA" };

export default async function MyFeedbackPage({ searchParams }: PageProps<"/me">) {
  const user = await getOptionalUser();
  if (!user) redirect("/");

  const params = parseFeedbackParams(await searchParams);
  const coveredBrands = user.memberships.filter((m) => m.role === "specialist");
  const [issueTypes, scores, issueCounts] = await Promise.all([
    listIssueTypes(),
    getMyBrandScores(),
    getMyIssueCounts(),
  ]);

  // Unknown values in the URL are ignored rather than answered with an error.
  const brand = coveredBrands.find((m) => m.slug === params.brand) ?? null;
  const activeIssue = issueTypes.find((it) => it.code === params.issue) ?? null;
  const active = { ...params, brand: brand?.slug ?? null, issue: activeIssue?.code ?? null };

  const scoredBrandIds = scores.map((s) => s.brandId);
  const [feed, recent] = await Promise.all([
    listMyFeedback({ brandId: brand?.brandId ?? null, issueCode: active.issue, search: active.q, page: active.page }),
    Promise.all(scoredBrandIds.map(async (id) => [id, await getMyRecentScores(id)] as const)),
  ]);
  const cards = arrangeBrandCards(user.memberships, scores, issueCounts, new Map(recent), issueTypes);
  const filtered = active.q !== null || active.brand !== null || active.issue !== null;

  return (
    <section className="flex flex-col gap-8">
      <header className="flex flex-col gap-2">
        <h1 className="font-display text-2xl font-bold tracking-tight">My feedback</h1>
        <p className="max-w-prose text-sm text-ink-muted">
          Reviews of the replies you sent. Only you and the leads of each brand can see them.
        </p>
      </header>

      {cards.length === 0 ? (
        <EmptyState
          title="No replies of your own"
          description="Feedback shows up here for the replies you send as a specialist. You do not cover any brand as a specialist."
        />
      ) : (
        <>
          <div className="grid gap-4 md:grid-cols-2">
            {cards.map((c) => (
              <BrandCard key={c.brandId} summary={c} />
            ))}
          </div>

          <div className="flex flex-col gap-4">
            <h2 className="text-sm font-semibold">Reviewed replies</h2>
            {scores.length === 0 ? (
              <EmptyState
                title="Nothing reviewed yet"
                description="Your leads review a few replies each day. Their scores and comments will appear here."
              />
            ) : (
              <>
                <FeedbackFilters brands={coveredBrands} params={active} activeIssue={activeIssue} />
                {feed.items.length > 0 ? (
                  <>
                    <FeedbackList items={feed.items} issueTypes={issueTypes} />
                    <Pagination params={active} total={feed.total} />
                  </>
                ) : feed.total > 0 ? (
                  <EmptyState
                    title="This page is past the end"
                    description={`There are ${feed.total} matching replies.`}
                    action={<FirstPageLink href={feedbackHref({ ...active, page: 1 })} label="Go to the first page" />}
                  />
                ) : filtered ? (
                  <EmptyState
                    title="No replies match"
                    description="Nothing matches this search and these filters. Try a ticket number or fewer filters."
                    action={<FirstPageLink href="/me" label="Clear all filters" />}
                  />
                ) : null}
              </>
            )}
          </div>
        </>
      )}
    </section>
  );
}

function FirstPageLink({ href, label }: { href: string; label: string }) {
  return (
    <Link href={href} className="text-sm font-medium text-accent underline-offset-2 hover:underline">
      {label}
    </Link>
  );
}
import Link from "next/link";
import { ScoreBadge } from "@/features/review/components/score-badge";
import { SEVERITY_TEXT } from "@/features/review/components/tones";
import { formatDate } from "@/server/time";
import { feedbackHref } from "../feedback-params";
import type { BrandFeedback } from "../summary";

/** Where the specialist stands in one brand, from their own reviews only. */
export function BrandCard({ summary }: { summary: BrandFeedback }) {
  const { score } = summary;

  return (
    <article className="flex min-w-0 flex-col gap-4 rounded-lg border border-line bg-surface p-4 sm:p-5">
      <header className="flex items-baseline justify-between gap-3">
        <h2 className="truncate font-display text-lg font-bold tracking-tight">{summary.name ?? "Former brand"}</h2>
        {score ? (
          <span
            className={`shrink-0 font-mono text-xs tabular-nums ${score.criticalCount > 0 ? "text-bad" : "text-ink-muted"}`}
          >
            {score.criticalCount} critical
          </span>
        ) : null}
      </header>

      {score === null ? (
        <p className="text-sm text-ink-muted">No reviews yet. They appear here once a lead reviews one of your replies.</p>
      ) : (
        <>
          <div className="flex flex-wrap items-end justify-between gap-x-6 gap-y-3">
            <div className="flex flex-col">
              <span className="text-xs text-ink-muted">
                {summary.name ? `Your average in ${summary.name}` : "Your average"}
              </span>
