                  />
                ) : filtered ? (
                  <EmptyState
                    title="No replies match"
                    description="Nothing matches this search and these filters. Try a ticket number or fewer filters."
                    action={<FirstPageLink href="/me" label="Clear all filters" />}
                  />
                ) : null}
              </>
            )}
          </div>
        </>
      )}
    </section>
  );
}

