import "server-only";

import { cache } from "react";
import { createClient } from "@/server/supabase/server";
import { ForbiddenError, UnauthorizedError } from "./errors";

export type BrandRole = "lead" | "specialist";

export type Membership = {
  brandId: string;
  slug: string;
  name: string;
  role: BrandRole;
};

export type CurrentUser = {
  id: string;
  fullName: string;
  memberships: Membership[];
};

/**
 * The signed-in person and their brands, or null without a session. Cached for
 * the duration of one request only (React cache), never across users.
 *
 * getUser() validates the token with Supabase Auth instead of trusting the
 * cookie as getSession() would.
 */
export const getOptionalUser = cache(async (): Promise<CurrentUser | null> => {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;

  const [profile, memberships] = await Promise.all([
    supabase.from("profiles").select("full_name").eq("id", user.id).single(),
    supabase
      .from("brand_memberships")
      .select("role, brand:brands!inner(id, slug, name)")
      .eq("user_id", user.id)
      .order("brand(name)"),
  ]);
  if (profile.error) throw profile.error;
  if (memberships.error) throw memberships.error;

  return {
    id: user.id,
    fullName: profile.data.full_name,
    memberships: memberships.data.map((m) => ({
      brandId: m.brand.id,
      slug: m.brand.slug,
      name: m.brand.name,
      role: m.role as BrandRole,
    })),
  };
});

/** The signed-in person; throws UnauthorizedError (401) without a session. */
export async function getCurrentUser(): Promise<CurrentUser> {
  const user = await getOptionalUser();
  if (!user) throw new UnauthorizedError();
  return user;
}

/**
 * The caller's membership in the brand with this slug. A brand that does not
 * exist and a brand the caller is not a member of both throw ForbiddenError, so
 * the answer never reveals which brands exist (TASK-003, Q9).
 */
export function requireMember(user: CurrentUser, brandSlug: string): Membership {
  const membership = user.memberships.find((m) => m.slug === brandSlug);
  if (!membership) throw new ForbiddenError();
  return membership;
}

/**
 * Throws ForbiddenError unless the caller leads this brand. Pass the brand_id
 * read from the database row being acted on, never one taken from the request.
 */
export function requireLeadOf(user: CurrentUser, brandId: string): Membership {
  const membership = user.memberships.find((m) => m.brandId === brandId);
  if (membership?.role !== "lead") throw new ForbiddenError();
  return membership;
}
import "server-only";

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { SUPABASE_COOKIE_OPTIONS } from "@/lib/supabase-cookie-options";
import type { Database } from "./database.types";

/**
 * A Supabase client for the current request, authenticated as whoever owns the
 * session cookie. Every query runs with that user's JWT, so RLS always applies.
 * There is deliberately no service_role client anywhere in the app.
 *
 * Create one per request (never share it at module level): it carries that
 * request's cookies.
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookieOptions: SUPABASE_COOKIE_OPTIONS,
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            for (const { name, value, options } of cookiesToSet) {
              cookieStore.set(name, value, options);
            }
          } catch {
            // Server Components cannot set cookies. The proxy refreshes the
            // session on every request, so a refresh lost here is not needed.
          }
        },
      },
    },
  );
}
      <header className="flex flex-col gap-2">
        <h1 className="font-display text-2xl font-bold tracking-tight">Hi, {user.fullName.split(" ")[0]}</h1>
        <p className="max-w-prose text-sm text-ink-muted">This is what the server grants you.</p>
        <div className="flex flex-wrap gap-2">
          {user.memberships.some((m) => m.role === "lead") ? (
            <Link
              href="/review"
              className="rounded-md bg-accent px-4 py-2 text-sm font-semibold text-accent-ink hover:opacity-90"
            >
              Open yesterday&apos;s review queue
            </Link>
          ) : null}
          {user.memberships.some((m) => m.role === "specialist") ? (
            <Link
              href="/me"
              className="rounded-md bg-accent px-4 py-2 text-sm font-semibold text-accent-ink hover:opacity-90"
            >
              See my feedback
            </Link>
          ) : null}
        </div>
      </header>

      {user.memberships.length === 0 ? (
        <EmptyState title="No brands yet" description="Ask a lead to add you to a brand." />
      ) : (
        <ul className="divide-y divide-line rounded-lg border border-line bg-surface">
          {user.memberships.map((m) => (
            <li key={m.brandId} className="flex items-center justify-between px-5 py-3">
              <span className="font-medium">{m.name}</span>
              <span className="font-mono text-2xs uppercase tracking-widest text-ink-muted">{m.role}</span>
            </li>
          ))}
        </ul>
      )}

      <div className="flex flex-col gap-2">
        <h2 className="text-sm font-semibold">Check the API</h2>
        <p className="text-sm text-ink-muted">A brand you are not part of answers 403.</p>
        <ul className="flex flex-wrap gap-2">
          {SEED_BRAND_SLUGS.map((slug) => (
            <li key={slug}>
              <a
                href={`/api/brands/${slug}/replies`}
                className="inline-block rounded-md border border-line bg-surface px-3 py-1.5 font-mono text-xs text-accent hover:border-accent"
              >
                /api/brands/{slug}/replies
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

