import { formatDuration } from "@/lib/format";
import type { ReplyDetail } from "@/server/data/replies";
import { formatClock, formatDate } from "@/server/time";

/**
 * The brand's key rule and response time, then the customer's message and the
 * reply that was sent. The customer sits on the sunken ground; the reply is
 * the page itself, set in the reading measure, because it is what gets judged.
 */
export function ReplyMessages({ reply }: { reply: ReplyDetail }) {
  const responseTime = formatDuration(Date.parse(reply.sentAt) - Date.parse(reply.receivedAt));
  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-2 rounded-lg border border-line bg-surface px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
        <p className="min-w-0 text-sm">
          <span className="font-semibold">{reply.brand.name}</span>
          <span className="text-ink-muted"> · {reply.brand.keyRule}</span>
        </p>
        <p className="shrink-0 font-mono text-2xs text-ink-muted">
          Replied in <span className="text-ink">{responseTime}</span>
        </p>
      </div>

      <section aria-label="Customer message" className="flex flex-col gap-2 rounded-lg bg-sunken px-4 py-4">
        <header className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 text-2xs text-ink-muted">
          <span className="font-semibold uppercase tracking-wider">Customer</span>
          <span className="font-mono">
            {formatDate(reply.receivedAt)} · {formatClock(reply.receivedAt)}
          </span>
        </header>
        <p className="text-sm font-medium">{reply.subject}</p>
        <p className="max-w-prose whitespace-pre-line text-sm text-ink-muted">{reply.customerMessage}</p>
      </section>

      <section
        aria-label="Sent reply"
        className="flex flex-col gap-2 rounded-lg border border-line-strong bg-surface px-4 py-4"
      >
        <header className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 text-2xs text-ink-muted">
          <span className="min-w-0 truncate">
            <span className="font-semibold uppercase tracking-wider text-ink">Sent reply</span> ·{" "}
            {reply.specialist.name}
          </span>
          <span className="font-mono">
            {reply.ticketRef} · {formatClock(reply.sentAt)}
          </span>
        </header>
        <p className="max-w-prose whitespace-pre-line text-base">{reply.replyBody}</p>
      </section>
    </div>
  );
}
import type { Severity } from "@/server/data/reviews";

/**
 * Severity and score are the only things that get semantic colour: critical is
 * bad, major is warn, minor stays neutral (docs/PLAN.md § 9).
 */
export const SEVERITY_ORDER: Severity[] = ["critical", "major", "minor"];

export const SEVERITY_LABEL: Record<Severity, string> = {
  critical: "Critical",
  major: "Major",
  minor: "Minor",
};

export const SEVERITY_TEXT: Record<Severity, string> = {
  critical: "text-bad",
  major: "text-warn",
  minor: "text-ink-muted",
};

/** A read-only issue chip. */
export const SEVERITY_CHIP: Record<Severity, string> = {
  critical: "border-bad/40 bg-bad-soft text-bad",
  major: "border-warn/40 bg-warn-soft text-warn",
  minor: "border-line bg-sunken text-ink-muted",
};

export function scoreTone(score: number): string {
  if (score <= 2) return "border-bad/40 bg-bad-soft text-bad";
  if (score === 3) return "border-warn/40 bg-warn-soft text-warn";
  return "border-good/40 bg-good-soft text-good";
}
import "server-only";

/**
 * The one time zone "yesterday" is measured in. Every brand in the seed works
 * from Spain, so a constant is enough today. It does not scale to a team spread
 * over time zones: the working day belongs to the brand, so the next step is a
 * brands.time_zone column, and this file is the only place that has to change
 * (TASK-004, Q1).
 */
export const APP_TIME_ZONE = "Europe/Madrid";

export type TimeRange = {
  /** Inclusive start, as an ISO instant. */
  start: string;
  /** Exclusive end, as an ISO instant. */
  end: string;
};

/** Yesterday's calendar day in APP_TIME_ZONE, as a half-open UTC range. */
export function yesterdayRange(now: Date = new Date()): TimeRange {
  const today = zonedDateParts(now);
  const start = zonedMidnight(today.year, today.month, today.day - 1);
  const end = zonedMidnight(today.year, today.month, today.day);
  return { start: start.toISOString(), end: end.toISOString() };
}

export function isWithin(instant: string, range: TimeRange): boolean {
  const t = Date.parse(instant);
  return t >= Date.parse(range.start) && t < Date.parse(range.end);
}

const clockFormat = new Intl.DateTimeFormat("en-GB", {
  timeZone: APP_TIME_ZONE,
  hour: "2-digit",
  minute: "2-digit",
});

const dateFormat = new Intl.DateTimeFormat("en-GB", {
  timeZone: APP_TIME_ZONE,
  day: "numeric",
  month: "short",
  year: "numeric",
});

/** "14:05" in APP_TIME_ZONE. */
export function formatClock(instant: string): string {
  return clockFormat.format(new Date(instant));
}

/** "24 Sept 2026" in APP_TIME_ZONE. */
export function formatDate(instant: string): string {
  return dateFormat.format(new Date(instant));
}

function zonedDateParts(instant: Date) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: APP_TIME_ZONE,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);
  const get = (type: Intl.DateTimeFormatPartTypes) => Number(parts.find((p) => p.type === type)?.value);
  return {
    year: get("year"),
    month: get("month"),
    day: get("day"),
    hour: get("hour"),
    minute: get("minute"),
    second: get("second"),
  };
}

/** Milliseconds APP_TIME_ZONE is ahead of UTC at this instant. */
function offsetAt(instant: Date): number {
  const p = zonedDateParts(instant);
  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - instant.getTime();
}

/**
 * 00:00 of a calendar day in APP_TIME_ZONE. Date.UTC normalises day 0 and
 * month overflow, so "day - 1" works across month and year boundaries. The
 * offset is taken twice because midnight and the UTC guess can fall on
 * opposite sides of a DST change.
 */
function zonedMidnight(year: number, month: number, day: number): Date {
  const guess = Date.UTC(year, month - 1, day);
  const first = guess - offsetAt(new Date(guess));
  return new Date(guess - offsetAt(new Date(first)));
}
