      count: (seen?.count ?? 0) + (r.flagged_count ?? 0),
      lastSentAt: seen && seen.lastSentAt > lastSentAt ? seen.lastSentAt : lastSentAt,
    });
  }
  return [...byCode.values()];
}

export type SpecialistScore = {
  specialistId: string;
  name: string;
  average: number;
  reviewCount: number;
  criticalCount: number;
};

