toolUseResult.originalFile:
import "server-only";

import { cache } from "react";
import { createClient } from "@/server/supabase/server";
import { ForbiddenError, UnauthorizedError } from "./errors";

export type BrandRole = "lead" | "specialist";

export type Membership = {
  brandId: string;
  slug: string;
  name: string;
  role: BrandRole;
};

export type CurrentUser = {
  id: string;
  fullName: string;
  memberships: Membership[];
};

/**
 * The signed-in person and their brands, or null without a session. Cached for
 * the duration of one request only (React cache), never across users.
 *
 * getUser() validates the token with Supabase Auth instead of trusting the
 * cookie as getSession() would.
 */
export const getOptionalUser = cache(async (): Promise<CurrentUser | null> => {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;

  const [profile, memberships] = await Promise.all([
    supabase.from("profiles").select("full_name").eq("id", user.id).single(),
    supabase
      .from("brand_memberships")
      .select("role, brand:brands!inner(id, slug, name)")
      .eq("user_id", user.id)
      .order("brand(name)"),
  ]);
  if (profile.error) throw profile.error;
  if (memberships.error) throw memberships.error;

  return {
    id: user.id,
    fullName: profile.data.full_name,
    memberships: memberships.data.map((m) => ({
      brandId: m.brand.id,
      slug: m.brand.slug,
      name: m.brand.name,
      role: m.role as BrandRole,
    })),
  };
});

/** The signed-in person; throws UnauthorizedError (401) without a session. */
export async function getCurrentUser(): Promise<CurrentUser> {
  const user = await getOptionalUser();
  if (!user) throw new UnauthorizedError();
  return user;
}

/**
 * The caller's membership in the brand with this slug. A brand that does not
 * exist and a brand the caller is not a member of both throw ForbiddenError, so
 * the answer never reveals which brands exist (TASK-003, Q9).
 */
export function requireMember(user: CurrentUser, brandSlug: string): Membership {
  const membership = user.memberships.find((m) => m.slug === brandSlug);
  if (!membership) throw new ForbiddenError();
  return membership;
}

/**
 * Throws ForbiddenError unless the caller leads this brand. Pass the brand_id
 * read from the database row being acted on, never one taken from the request.
 */
export function requireLeadOf(user: CurrentUser, brandId: string): Membership {
  const membership = user.memberships.find((m) => m.brandId === brandId);
  if (membership?.role !== "lead") throw new ForbiddenError();
  return membership;
}

import type { Metadata } from "next";
import { notFound, redirect } from "next/navigation";
import { FrequentIssues } from "@/features/brand-overview/components/frequent-issues";
import { SpecialistTable } from "@/features/brand-overview/components/specialist-table";
import { TrendSection } from "@/features/brand-overview/components/trend-section";
import { summarizeTrend } from "@/features/brand-overview/trend";
import { getOptionalUser } from "@/server/auth/session";
import {
  TREND_WEEKS,
  getBrand,
  getBrandIssueCounts,
  getBrandTrend,
  getSpecialistScores,
} from "@/server/data/brand-overview";
import { listIssueTypes } from "@/server/data/reviews";
import { EmptyState } from "@/ui/empty-state";
import { LinkButton } from "@/ui/link-button";

export const metadata: Metadata = { title: "Brand overview · Sellervate QA" };

export default async function BrandPage({ params }: PageProps<"/brands/[slug]">) {
  const user = await getOptionalUser();
  if (!user) redirect("/");

  // Only a lead of the brand gets the page. The membership comes from the
  // database; the slug only picks which one. Anyone else, and a slug that does
  // not exist, get the same not found, so the page never confirms a brand
  // exists (TASK-006, Q1).
  const { slug } = await params;
  const membership = user.memberships.find((m) => m.slug === slug && m.role === "lead");
  if (!membership) notFound();
  const brand = await getBrand(membership.brandId);
  if (!brand) notFound();

  const [trend, issueCounts, specialists, issueTypes] = await Promise.all([
    getBrandTrend(brand.id),
    getBrandIssueCounts(brand.id),
    getSpecialistScores(brand.id),
    listIssueTypes(),
  ]);
  const summary = summarizeTrend(trend.weeks);

  return (
    <section className="flex flex-col gap-8">
      <header className="flex min-w-0 flex-col gap-2">
        <p className="font-mono text-2xs uppercase tracking-widest text-ink-muted">Brand overview</p>
        <h1 className="truncate font-display text-2xl font-bold tracking-tight">{brand.name}</h1>
        <p className="max-w-prose text-sm text-ink-muted">{brand.keyRule}</p>
      </header>

      {specialists.length === 0 ? (
        <EmptyState
          title={`No reviews yet for ${brand.name}`}
          description="Reviews from the queue show up here, grouped by the week each reply was sent."
          action={<LinkButton href={`/review?brand=${brand.slug}`}>Open the review queue</LinkButton>}
        />
      ) : (
        <>
          <TrendSection weeks={trend.weeks} events={trend.events} summary={summary} weekCount={TREND_WEEKS} />
          <div className="grid gap-6 lg:grid-cols-2">
            <FrequentIssues counts={issueCounts} issueTypes={issueTypes} />
            <SpecialistTable specialists={specialists} />
          </div>
        </>
      )}
    </section>
  );
}

